<template>
  <view class="page"><view class="header"><text class="back" @tap="goBack">‹</text><text class="title">我的收藏</text><view class="space" /></view><view v-if="loading" class="empty">正在加载收藏...</view><view v-else-if="!favorites.length" class="empty"><text class="empty-icon">☆</text><text>还没有收藏内容</text></view><view v-else class="list"><view v-for="post in favorites" :key="post.id" class="card" @tap="openPost(post)"><view class="card-head"><view class="avatar">农</view><view class="author"><text class="name">{{ post.authorId || '农友' }}</text><text class="date">{{ post.createdAt }}</text></view><text class="crop">{{ post.crop }}</text></view><text class="description">{{ post.description || '暂无内容' }}</text><view class="actions" @tap.stop><view class="action active" @tap.stop="removeFavorite(post.id)"><uni-icons type="star-filled" size="20" color="#ffad2f" /><text>已收藏</text></view><view class="action" @tap.stop="openPost(post)"><text>查看详情</text><text class="arrow">›</text></view></view></view></view></view>
</template>
<script>
export default { data() { return { posts: [], loading: false } }, computed: { favorites() { const saved = uni.getStorageSync('hospitalPostFavorites') || {}; return this.posts.filter(post => saved[post.id]) } }, onShow() { this.loadPosts() }, methods: { goBack() { uni.navigateBack() }, loadPosts() { this.loading = true; uni.request({ url: 'http://123.57.255.171:8080/mobile/posts', method: 'GET', success: res => { const body = res.data || {}; if (body.code === 200 && Array.isArray(body.data)) this.posts = body.data.map(post => ({ id: post.postId, authorId: post.authorId || post.authorAccount, crop: post.crop, description: post.description, createdAt: post.createdAt })) }, fail: () => uni.showToast({ title: '无法加载收藏内容', icon: 'none' }), complete: () => { this.loading = false } }) }, removeFavorite(postId) { const saved = { ...(uni.getStorageSync('hospitalPostFavorites') || {}) }; delete saved[postId]; uni.setStorageSync('hospitalPostFavorites', saved); uni.showToast({ title: '已取消收藏', icon: 'none' }) }, openPost(post) { uni.navigateTo({ url: '/pages/hospital/detail?id=' + post.id }) } } }
</script>
<style scoped>.page { min-height: 100vh; background: #f4f6f5; }.header { height: 100rpx; padding: 0 30rpx; display: flex; align-items: center; justify-content: space-between; background: #46d69d; }.back { width: 64rpx; color: #fff; font-size: 70rpx; }.title { color: #14583d; font-size: 34rpx; font-weight: 600; }.space { width: 64rpx; }.list { padding: 18rpx 20rpx; }.card { margin-bottom: 18rpx; padding: 26rpx 24rpx 0; border-radius: 12rpx; background: #fff; }.card-head { display: flex; align-items: center; }.avatar { width: 68rpx; height: 68rpx; border-radius: 50%; background: #a9edc9; color: #287c56; font-size: 29rpx; line-height: 68rpx; text-align: center; }.author { flex: 1; margin-left: 16rpx; }.name { display: block; font-size: 29rpx; font-weight: 600; }.date { display: block; margin-top: 5rpx; color: #a0aaa5; font-size: 22rpx; }.crop { color: #7d8983; font-size: 23rpx; }.description { display: block; margin: 22rpx 0; color: #59655f; font-size: 28rpx; line-height: 42rpx; }.actions { height: 76rpx; display: flex; align-items: center; justify-content: space-between; border-top: 1rpx solid #f0f2f1; }.action { display: flex; align-items: center; color: #98a19c; font-size: 24rpx; }.action text { margin-left: 7rpx; }.action.active { color: #ffad2f; }.empty { min-height: 560rpx; display: flex; flex-direction: column; align-items: center; justify-content: center; color: #9ba8a1; font-size: 27rpx; }.empty-icon { margin-bottom: 18rpx; color: #ffad2f; font-size: 70rpx; }</style>
